GimCorpus.put(456,0,[[1,7,"שנאמר וקצותה את כפה וכו'. א\"א בספרי קא דריש לה הכי עכ\"ל:",1,0],[4,1,"המתכוון להרוג את זה והרג את זה פטור ממיתת בית דין וכו'. א\"א כר\"ש הוא ואין הלכה כר\"ש עכ\"ל:",1,0],[5,2,"אבל אם חבל בו בשגגה אף על פי שאמדוהו למיתה וכו' עד קירב את מיתת עצמו. א\"א נמצא לדבריו מה שאמרו חובשין אותו דאי מיית קטלינן ליה לא אמרו אלא במכה שאין בה חבורה ולא מחוור כלל. ואומר אני שלא אמרו הרוח בלבלתו או פרכוסו הרגתו אלא כששחט בו שנים או רוב שנים אבל חבורה אחרת אין הרוח ופרכוס מקרבין את מיתתו:",1,0],[5,3,"ישראל שהרג בשגגה את העבד או את גר תושב. א\"א אין נ\"ל כך מן ההלכה לפי שהוצרכו להביא עבד ועובד כוכבים מן הריבוי אלמא גר תושב אין גולין עליו ואין נהרג עליו ועוד כי יכה את רעהו כתיב עכ\"ל:",1,0],[5,6,"וכן הרב המכה תלמידו או שליח בין דין שהכה את בעל דין הנמנע מלבא בדין וכו'. א\"א זו לא שמענו מעולם אלא שליח ב\"ד שהוא מלקה יותר ממה שאמדוהו ב\"ד ומת תחת ידו והא דאמרינן דכפתינן ואסרינן ועבדינן הרדפה הנהו לבעלי עבירות עד שיחזרו בהן:",1,0],[6,5,"וכן כל הרצחנים שהרגו בעד אחד או בלא התראה וכו'. א\"א תימה הוא ואיך נאמין בעד אחד או להתיר דמו של זה לגואל הדם:",1,0],[7,6,"עיר מקלט שיש בה רוצחים. א\"א שיש בה רוב רצחנים עכ\"ל:",1,0],[8,7,"וכן מושחין בין כל עיר וכו'. א\"א וכן משוין. עכ\"ל:",1,0],[9,10,"נמצא זה על גבי זה מודדין מן העליון כמות שהן מונחין. א\"א זה הפסק אינו מתברר מהגמרא:",1,0],[9,14,"אשה אומרת ראיתי את ההורג עד בין שבאו שתיהן כאחת בין שבאו זו אחר זו. א\"א נראה מן הגמרא שזה שיבוש הוא דבזה אחר זה הראשון עיקר ואפילו אשה עכ\"ל:",1,0],[9,15,"אבל אם אמר עד אחד וכו'. א\"א גם זה שיבוש:",1,0],[9,16,"שתי נשים או שני פסולין אומרים וכו' עד עורפין. א\"א גם זה שיבוש שלא אמרו אלא בדאתא עד אחד כשר מעיקרא אבל אתא לבסוף הולכים אחר רוב דעות ואפילו בעד אחד מכחישן עכ\"ל:",1,0],[9,17,"שלש נשים או שלשה פסולים וכו'. א\"א אפילו בזה אחר זה עכ\"ל:",1,0],[11,3,"גובה המעקה אין פחות מעשרה טפחים. א\"א דוקא ממקום דרסו והוא מקום הנמוך שבו אבל שאר צדדין ג' טפחים עכ\"ל:",1,0],[12,5,"וכן לא יתן אדם פס ידו וכו'. א\"א בירושלמי אסור למיתן פיסתא תותי בי שחיא ומפרשין חתיכה של בשר או של לחם מפני הזיעה עכ\"ל:",1,0],[12,5,"ולא יתן התבשיל וכו'. א\"א גם זה בירושלמי ומפרשים משום רוח רעה:",2,0],[12,6,"וכן לא ינעוץ וכו'. א\"א גם זה מפרשים משום ביזוי שעושה מהן תיק לסכין:",1,0],[13,10,"חמרים שרגליו של אחד מהן רעועות אין חביריו רשאין להקדים ולעבור מעליו. פירוש אין חביריו רשאין לדרוס עליו ולעבור אבל אם נפל רשאין ודוקא בחמור אבל באדם לא עכ\"ל:",1,0]]);
